// R1-T3 authored props (D-057): builds the per-hood street kit as SVG.
// Writes art/arenas/props/<theme>-<kind>-<variant>.svg (review copies) and js/view/arena-props-data.js (what the game loads;
// SVG as strings, so it works from file://). Source: tools/arena-props/<theme>.js, helpers in tools/arena-props/lib.js.
// Usage: node prototype/tools/gen-arena-props.js
'use strict';
const fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..', '..');
const THEMES = ['istiklal', 'bazaar', 'atakoy'];

const dir = path.join(ROOT, 'art', 'arenas', 'props'); fs.mkdirSync(dir, { recursive: true });
const data = {}, report = [];
THEMES.forEach(id => {
  const file = path.join(__dirname, 'arena-props', id + '.js');
  if (!fs.existsSync(file)) return;
  const kit = require(file);
  data[id] = {};
  Object.keys(kit).forEach(kind => {
    data[id][kind] = kit[kind].map((p, v) => {
      fs.writeFileSync(path.join(dir, id + '-' + kind + '-' + v + '.svg'), p.svg);
      return { w: p.w, h: p.h, ax: p.ax, ay: p.ay, fw: p.fw, fd: p.fd, svg: p.svg, label: p.label || null };
    });
    report.push(id + '.' + kind + 'x' + kit[kind].length);
  });
});
const out = '// GENERATED by tools/gen-arena-props.js (R1-T3, D-057). Do not edit by hand. Source: art/arenas/props/*.svg.\n' +
  'P.ArenaPropsData = ' + JSON.stringify(data) + ';\n';
fs.writeFileSync(path.join(ROOT, 'prototype', 'js', 'view', 'arena-props-data.js'), out);
console.log('arena props: ' + report.join(' ') + ', ' + (out.length / 1024).toFixed(0) + ' KB');
